    "Content-Type": "application/json"
};

msg.method = "PUT";

msg.url = "https://esp32-iot-dashboard-6b724-default-rtdb.europe-west1.firebasedatabase.app/current/temperature.json";

msg.payload = {
    value: msg.payload,
    timestamp: Date.now()
};
let data = global.get("firebaseData") || {};

data.temperature = msg.payload.value;

global.set("firebaseData", data);

return msg;

